import sys,os
import numpy as np
from PIL import Image
n=int(sys.argv[1])
S=Image.open('D:/Coding/BYMR/art-trials/rezghul-anim/rezghul-fix@4x.png').convert('RGBA')
c=np.array(S.crop((n*192,0,n*192+192,172))); c[...,3]=np.where(c[...,3]>200,255,0)
c=Image.fromarray(c,'RGBA').resize((576,516),Image.LANCZOS)
bg=Image.new('RGBA',c.size,(255,0,255,255)); bg.alpha_composite(c)
os.makedirs(f'h{n}',exist_ok=True)
bg.convert('RGB').save(f'h{n}/ref.png')
deg=n*12
def facing_text(n):
    if n<=5: return 'seen from the side, facing screen-right: the head with its wide fanged mouth is at the upper right looking right, one clawed arm reaches forward and down to the right, the green vortex body sweeps down to the lower left and its tail curls out to the left'
    if n==6: return 'seen three-quarter from the front-right: the head and fanged mouth face right and slightly toward the viewer, the arms spread, the vortex tail curls down to the lower left'
    if n<=9: return 'seen head-on from the front: the head with its big fanged mouth faces the viewer, both clawed arms spread out to the sides, the vortex narrows down to a tail that curls out to one side'
    if n<=13: return 'seen three-quarter from the front-left: the head and fanged mouth face left and slightly toward the viewer, the vortex tail curls down to the lower right'
    if n<=19: return 'seen from the side, facing screen-left: the head with its wide fanged mouth is at the upper left looking left, one clawed arm reaches forward to the left, the green vortex body sweeps down to the lower right and its tail curls out to the right'
    if n<=27: return 'seen from BEHIND: the viewer sees the spiny orange back with a row of cream spikes down the spine, the broad shoulders, both arms spread out to the sides, the horned head from behind, and the green vortex tail below; the face, eyes and mouth are NOT visible at all'
    if n==28: return 'seen from behind-right with the head just turning: the spiny back and shoulders face the viewer, only a sliver of the fanged mouth shows at the right edge of the head'
    return 'seen from behind-right with the head turned to the right: the spiny back faces the viewer and the fanged mouth is seen in profile at the right, the vortex tail curls to the lower left'
FT=facing_text(n)
BACKS=set(range(20,28))
KNOB="the TAIL KNOB: the very tip of the long curling green tail ends in a small round dark purple-black ball (about the size of a large pea next to the body) with a faint highlight; this knob must be present at the tip of the tail in EVERY cell, exactly as in ref.png"
STRICT=f"FACING RULE (most important): at heading {deg} degrees (number {n} of 30) this Rezghul is {FT}, exactly as ref.png shows. In EVERY cell, walk cells AND attack cells (the anticipation, the wind-up, the strike, the follow-through), the head, the arms and the body point this same way as ref.png and the viewer sees the same side of the creature as in ref.png. The wind-up must NOT turn to face the viewer and must NOT turn sideways unless ref.png does so; the creature keeps ref.png's orientation. Keep exactly the parts ref.png shows in every cell: ONE horned head with a wide fanged mouth (when ref.png shows the face), a muscular spiny orange-red torso, exactly TWO clawed arms with cream claws (count them in ref.png; a far arm hidden in ref.png stays hidden), one swirling emerald-green vortex body with a dark hole (black spiral hole) in it, one long curling green tail, and {KNOB}. No legs, no wings, no extra tails.\n"
BACK=("Rezghul is seen from BEHIND at this heading: NO face, NO eyes and NO mouth visible in ANY cell, attack cells included. The spiny back, spine spikes, horns and claws only. Attack = the creature rears back and lunges forward away from the viewer, showing only its back.\n" if n in BACKS else "")
P=f"""{STRICT}Use the reference image ref.png (the exact creature: the painted game sprite of Rezghul, shown at heading {deg} degrees; match its facing, colours, spikes, claws and part placement exactly) and portrait.png (the concept painting, style reference only; ref.png wins on pose, size, colour and part count).
Camera is a 3/4 isometric view from above. Copy ref.png's facing direction exactly in every cell; never mirror. The exact viewing angle of ref.png must be kept in EVERY cell, walk cells included.

Create ONE image: an animation pose sheet of this same creature on flat pure magenta #FF00FF, no shadows, no ground, no text, no grid lines. Layout: EXACTLY 4 columns x 3 rows of equal cells (12 cells, never a 4th row), poses in reading order: row 1 = cells 1-4 (walk 1-4), row 2 = cells 5-8 (walk 5, walk 6, anticipation, wind-up), row 3 = cells 9-12 (strike, follow-through, recovery, empty). Exactly 6 walk poses, no more. The creature is Rezghul: a floating fanged demon with an orange-red muscular spiny upper body and a swirling emerald-green vortex (no legs) that narrows into a long curling green tail ending in a dark knob, as ref.png and portrait.png show. Exactly one creature, exactly the parts ref.png shows, the same colours as ref.png (deep orange-red skin with darker shading and cream claws, emerald-to-teal green vortex with bright cyan-green swirl highlights, dark purple-black tail knob), the same painted detail (the dense scales, spikes and swirling energy texture of ref.png; do not smooth or lighten it), nothing added. {BACK}Cells 1-6 are a floating GLIDE-WALK: Rezghul hovers forward in the facing direction with no legs, the vortex body sways and swirls, the torso rocks gently forward and back, the head bobs, the two arms swing alternately (one forward and up, the other back and down, swapping each step), and the tail curl swishes side to side; make the six walk poses clearly different from each other: each arm swings at least a full hand-length between its forward and back positions, the torso leans visibly, the tail curl swings; the tail knob stays attached to the tail tip in every cell. The creature stays horizontally centred in its cell, the lowest point of the tail on about the same horizontal line in every cell, the creature the same overall size as ref.png (do not grow or shrink it between cells).
Cells 7-11 are an ATTACK: 7 anticipation: the creature hunches down and back, arms drawn in toward the chest, head lowered, mouth slightly open; 8 wind-up: it rears up and back, both arms raised high and wide with claws spread, mouth wide open; 9 strike: it lunges forward in the facing direction, claws slashing forward, mouth wide and snapping; 10 follow-through: furthest forward, arms swept down and across, body stretched; 11 recovery: settling back to the resting pose of ref.png. Cell 12 stays empty magenta.
In EVERY cell it must be the identical creature as ref.png in the same painted style (soft detailed shading, no black outline), same camera angle and the same size as ref.png in the walk cells. Keep the same heading in all cells. No motion-streak arcs, speed lines, sparks, lightning bolts, smoke or glow effects outside the body; the green vortex stays inside its own silhouette. Do not crop any part at the cell edges and keep clear magenta between the cells. A children's-game creature illustration.
Use your image generation tool (one call) and save the result as sheet.png in the current folder. Do not write code and do not copy or composite pixels from the inputs.
"""
open(f'h{n}/prompt.txt','w').write(P)
